CAT = "dethVerhalten"; SEG = "VER"
# Verhalten im Verkehr.
Q = [
("Auf einer Autobahn mit vier Fahrstreifen je Richtung stockt der Verkehr. Wo bilden Sie die Rettungsgasse?",
 "Zwischen dem ersten und zweiten Streifen von links", ["Zwischen dem zweiten und dritten Streifen von links", "Auf dem Seitenstreifen", "Erst wenn ein Einsatzfahrzeug kommt"],
 "§ 11 Abs. 2 StVO: Die Gasse entsteht zwischen dem äußerst linken und dem unmittelbar rechts daneben liegenden Fahrstreifen, sobald der Verkehr mit Schrittgeschwindigkeit fährt oder steht."),
("Ab wann muss auf der Autobahn eine Rettungsgasse gebildet werden?",
 "Sobald Schrittgeschwindigkeit gefahren wird", ["Erst beim Martinshorn", "Erst nach fünf Minuten Stillstand", "Nur auf Anweisung der Polizei"],
 "Die Rettungsgasse ist schon zu bilden, wenn der Verkehr stockt, nicht erst, wenn ein Einsatzfahrzeug zu hören ist."),
("Ein Fahrstreifen endet, der Verkehr ist dicht. Wo fädeln die Fahrzeuge nach dem Reißverschlussverfahren ein?",
 "Unmittelbar vor der Engstelle", ["Sobald das Warnschild auftaucht", "Etwa 200 m vor der Engstelle", "Erst hinter der Engstelle"],
 "§ 7 Abs. 4 StVO: Fahrzeuge auf dem durchgehenden Fahrstreifen lassen unmittelbar vor Beginn der Verengung jeweils ein Fahrzeug abwechselnd einfädeln."),
("Welchen Seitenabstand müssen Sie innerorts beim Überholen eines Radfahrers mindestens einhalten?",
 "1,5 m", ["0,5 m", "1 m", "2 m"],
 "§ 5 Abs. 4 StVO: Beim Überholen von Radfahrern, Fußgängern und E-Scootern gilt innerorts ein Seitenabstand von mindestens 1,5 m."),
("Welchen Seitenabstand müssen Sie außerorts beim Überholen eines Radfahrers mindestens einhalten?",
 "2 m", ["1 m", "1,5 m", "3 m"],
 "§ 5 Abs. 4 StVO verlangt außerorts mindestens 2 m Seitenabstand zu Radfahrern, Fußgängern und E-Scooter-Fahrern."),
("Sie fahren auf einer Landstraße hinter einem Radfahrer. Wegen Gegenverkehrs können Sie ihn nicht mit 2 m Seitenabstand überholen. Was tun Sie?",
 "Hinter dem Radfahrer bleiben", ["Mit weniger Abstand überholen", "Hupen und dann überholen", "Rechts am Radfahrer vorbeifahren"],
 "Kann der vorgeschriebene Abstand nicht eingehalten werden, darf nicht überholt werden. Warten Sie, bis die Strecke frei ist."),
("Auf welcher Seite überholen Sie grundsätzlich?",
 "Links", ["Rechts", "Auf der freieren Seite", "Auf dem Seitenstreifen"],
 "§ 5 Abs. 1 StVO: Es ist links zu überholen. Ausnahmen gibt es zum Beispiel bei Linksabbiegern und Schienenfahrzeugen."),
("Ein Fahrzeug vor Ihnen hat links geblinkt und sich zur Mitte eingeordnet. Wie dürfen Sie es überholen?",
 "Rechts", ["Links", "Gar nicht", "Nur nach Hupen"],
 "§ 5 Abs. 7 StVO: Wer sich zum Linksabbiegen eingeordnet und die Absicht angekündigt hat, ist rechts zu überholen."),
("Auf welcher Seite überholen Sie eine Straßenbahn in einer Straße mit Verkehr in beiden Richtungen?",
 "Rechts", ["Links", "Auf jeder Seite", "Gar nicht"],
 "Schienenfahrzeuge werden rechts überholt. Nur in Einbahnstraßen oder wenn die Schienen zu weit rechts liegen, darf links überholt werden."),
("Wann ist Überholen verboten?",
 "Bei unklarer Verkehrslage", ["Auf Straßen mit Leitlinie", "Bei trockener Fahrbahn", "Außerhalb geschlossener Ortschaften"],
 "§ 5 Abs. 3 StVO: Überholen ist bei unklarer Verkehrslage verboten, also wenn nicht sicher ist, was die anderen tun werden."),
("Sie werden überholt. Was dürfen Sie nicht tun?",
 "Ihre Geschwindigkeit erhöhen", ["Weiter rechts fahren", "Die Geschwindigkeit halten", "Den Abstand nach vorn halten"],
 "§ 5 Abs. 6 StVO: Wer überholt wird, darf seine Geschwindigkeit nicht erhöhen."),
("Wie benutzen Sie den Blinker in einem Kreisverkehr mit Zeichen 215?",
 "Nur beim Ausfahren rechts blinken", ["Beim Einfahren rechts blinken", "Beim Einfahren links blinken", "Gar nicht, der Kreisverkehr hat Vorfahrt"],
 "§ 9a StVO: Beim Einfahren in den Kreisverkehr wird nicht geblinkt, beim Ausfahren muss rechts geblinkt werden."),
("Wie schnell dürfen Sie innerhalb geschlossener Ortschaften höchstens fahren, wenn kein Zeichen etwas anderes anordnet?",
 "50 km/h", ["60 km/h", "70 km/h", "80 km/h"],
 "§ 3 Abs. 3 StVO: Innerorts gilt für alle Kraftfahrzeuge 50 km/h, soweit Zeichen nichts anderes anordnen."),
("Wie schnell dürfen Sie mit einem Pkw außerorts auf einer Landstraße höchstens fahren, wenn nichts anderes angeordnet ist?",
 "100 km/h", ["80 km/h", "90 km/h", "120 km/h"],
 "§ 3 Abs. 3 StVO: Für Pkw gilt außerorts 100 km/h. Auf Autobahnen gibt es grundsätzlich kein allgemeines Tempolimit."),
("Welche Richtgeschwindigkeit wird auf Autobahnen empfohlen?",
 "130 km/h", ["100 km/h", "120 km/h", "150 km/h"],
 "Nach der Autobahn-Richtgeschwindigkeits-Verordnung wird empfohlen, auch bei guten Bedingungen nicht schneller als 130 km/h zu fahren."),
("Was ist auf der Autobahn verboten?",
 "Wenden und Rückwärtsfahren", ["Überholen auf dem linken Streifen", "Fahren mit Abblendlicht", "Fahren mit Tempomat"],
 "§ 18 Abs. 7 StVO: Wenden und Rückwärtsfahren sind auf Autobahnen und Kraftfahrstraßen verboten, auch wenn Sie eine Ausfahrt verpasst haben."),
("Welche Fahrzeuge dürfen Autobahnen benutzen?",
 "Kfz, die bauartbedingt über 60 km/h fahren", ["Alle Kraftfahrzeuge ohne jede Ausnahme", "Kfz, die bauartbedingt über 25 km/h fahren", "Auch Fahrräder mit Hilfsmotor"],
 "§ 18 Abs. 1 StVO: Autobahnen und Kraftfahrstraßen sind Kraftfahrzeugen vorbehalten, deren bauartbedingte Höchstgeschwindigkeit mehr als 60 km/h beträgt."),
("Sie haben auf der Autobahn eine Panne. Wo stellen Sie das Warndreieck auf?",
 "Etwa 200 m hinter dem Fahrzeug", ["Etwa 50 m hinter dem Fahrzeug", "Direkt auf dem Fahrzeugdach", "Etwa 20 m vor dem Fahrzeug"],
 "§ 15 StVO verlangt eine ausreichende Entfernung. Auf Autobahnen werden etwa 200 m empfohlen (mindestens 150 m), damit Nachfolgende früh genug reagieren können."),
("Sie haben auf einer Landstraße eine Panne. In welcher Entfernung stellen Sie das Warndreieck etwa auf?",
 "100 m", ["10 m", "25 m", "50 m"],
 "§ 15 StVO nennt für schnellen Verkehr etwa 100 m. Auf Landstraßen gilt also etwa 100 m, innerorts etwa 50 m und auf Autobahnen etwa 200 m. Vor Kurven und Kuppen früher warnen."),
("Was tun Sie bei einer Panne auf der Autobahn zuerst, nachdem Sie auf dem Seitenstreifen angehalten haben?",
 "Warnblinklicht an, Warnweste anziehen", ["Sofort den Reifen wechseln", "Im Auto sitzen bleiben und warten", "Hinter dem Auto auf der Fahrbahn winken"],
 "Erst sichern Sie sich selbst: Warnblinklicht, Warnweste, alle Insassen hinter die Schutzplanke, dann das Warndreieck aufstellen."),
("Wo sollen sich die Insassen nach einer Panne auf der Autobahn aufhalten?",
 "Hinter der Schutzplanke", ["Im Fahrzeug mit Gurt", "Auf dem Seitenstreifen vor dem Auto", "Zwischen Auto und Leitplanke"],
 "Hinter der Schutzplanke sind sie vor auffahrenden Fahrzeugen geschützt. Im oder am Auto ist es auf dem Seitenstreifen sehr gefährlich."),
("Sie erreichen als erstes Fahrzeug eine Unfallstelle mit Verletzten. Was ist richtig?",
 "Absichern, 112 rufen, Erste Hilfe leisten", ["Weiterfahren, Helfer kommen sicher bald", "Nur Fotos für die Polizei machen", "Verletzte sofort aus dem Auto ziehen"],
 "Wer nicht hilft, obwohl es zumutbar ist, macht sich nach § 323c StGB strafbar. Erst die Unfallstelle sichern, dann Notruf und Erste Hilfe."),
("Sie waren an einem Unfall mit Sachschaden beteiligt. Wann dürfen Sie den Unfallort verlassen?",
 "Nach Feststellung der Personalien", ["Sofort, wenn niemand verletzt ist", "Nach einer Wartezeit von fünf Minuten", "Wenn Sie einen Zettel hinterlassen"],
 "Wer sich vorher entfernt, begeht Unfallflucht (§ 142 StGB). Ein Zettel an der Windschutzscheibe reicht nicht."),
("Sie haben ein parkendes Auto beschädigt, der Halter ist nicht da. Was tun Sie nach einer angemessenen Wartezeit?",
 "Die Polizei benachrichtigen", ["Einen Zettel hinterlassen und fahren", "Einfach weiterfahren", "Den Schaden fotografieren und fahren"],
 "Nach angemessener Wartezeit müssen Sie die Feststellungen unverzüglich nachträglich ermöglichen, etwa über die Polizei. Ein Zettel genügt nicht."),
("Wie lange dürfen Sie halten, ohne dass es als Parken gilt, wenn Sie beim Fahrzeug bleiben?",
 "Bis zu 3 Minuten", ["Bis zu 1 Minute", "Bis zu 10 Minuten", "Bis zu 30 Minuten"],
 "§ 12 Abs. 2 StVO: Wer sein Fahrzeug verlässt oder länger als drei Minuten hält, der parkt. Ein- und Aussteigen oder Be- und Entladen bleibt Halten."),
("Wie weit vor den Schnittpunkten der Fahrbahnkanten einer Kreuzung ist Parken verboten?",
 "5 m", ["3 m", "10 m", "15 m"],
 "§ 12 Abs. 3 StVO: Unzulässig ist das Parken vor und hinter Kreuzungen und Einmündungen bis zu je 5 m von den Schnittpunkten der Fahrbahnkanten."),
("Wie weit vor und hinter einem Haltestellenschild für Busse ist Parken verboten?",
 "15 m", ["5 m", "8 m", "10 m"],
 "§ 12 Abs. 3 StVO: Vor und hinter Haltestellenschildern (Zeichen 224) ist das Parken bis zu je 15 m verboten."),
("Wo ist Parken verboten?",
 "Vor Grundstückseinfahrten", ["Am rechten Fahrbahnrand", "Auf gekennzeichneten Parkflächen", "In einer Tempo-30-Zone"],
 "§ 12 Abs. 3 StVO: Vor Grundstücksein- und -ausfahrten darf nicht geparkt werden, auf schmalen Fahrbahnen auch nicht gegenüber."),
("Wo ist bereits das Halten verboten?",
 "Auf Fußgängerüberwegen", ["Am rechten Fahrbahnrand", "Vor einer Garage auf der Straße", "In einer Spielstraße auf Parkflächen"],
 "§ 12 Abs. 1 StVO: Halten ist unter anderem auf und bis zu 5 m vor Fußgängerüberwegen verboten."),
("Sie wollen in einer Straße mit Parkscheibenpflicht parken. Wie stellen Sie die Parkscheibe ein?",
 "Auf den Strich der nächsten halben Stunde", ["Auf die volle Stunde davor", "Auf die geplante Abfahrtszeit des Fahrzeugs", "Auf die aktuelle Minute genau"],
 "Die Parkscheibe wird auf den Strich der halben Stunde gestellt, die auf den Zeitpunkt des Anhaltens folgt."),
("Warum müssen Sie vor dem Fahrstreifenwechsel über die Schulter blicken?",
 "Wegen des toten Winkels der Spiegel", ["Weil der Innenspiegel verboten ist", "Damit der Blinker länger leuchtet", "Weil die Spiegel spiegelverkehrt sind"],
 "Neben und schräg hinter dem Auto gibt es Bereiche, die kein Spiegel zeigt. Der Schulterblick deckt diesen toten Winkel ab."),
("Was gilt für das Rechtsfahrgebot auf der Autobahn bei freier Strecke?",
 "Möglichst weit rechts fahren", ["Immer den mittleren Streifen nutzen", "Den linken Streifen frei wählen", "Nur zum Abbiegen rechts fahren"],
 "§ 2 Abs. 2 StVO: Es ist möglichst weit rechts zu fahren. Wer ohne Grund links oder in der Mitte bleibt, behindert andere."),
("Sie wollen innerorts auf einer Straße mit zwei markierten Fahrstreifen je Richtung fahren. Was ist erlaubt?",
 "Den Fahrstreifen frei wählen", ["Nur den rechten Fahrstreifen nutzen", "Nur bei Stau links fahren", "Nur Lkw dürfen rechts fahren"],
 "§ 7 Abs. 3 StVO: Innerorts dürfen Pkw auf Fahrbahnen mit mehreren markierten Fahrstreifen je Richtung den Fahrstreifen frei wählen."),
("Ein Einsatzfahrzeug nähert sich mit Blaulicht und Martinshorn. Was müssen Sie tun?",
 "Sofort freie Bahn schaffen", ["Weiterfahren wie bisher", "Sofort auf der Fahrbahn anhalten", "Mit Lichthupe Platz verlangen"],
 "§ 38 Abs. 1 StVO: Blaues Blinklicht zusammen mit Einsatzhorn ordnet an, dass alle sofort freie Bahn zu schaffen haben."),
("Sie werden bei Dunkelheit auf einer Landstraße überholt. Wann blenden Sie ab?",
 "Sobald der Überholende neben Ihnen ist", ["Erst wenn er wieder vor Ihnen eingeschert ist", "Gar nicht, er fährt ja dann voraus", "Nur wenn Gegenverkehr kommt"],
 "Wer überholt wird, blendet ab, sobald der Überholende auf gleicher Höhe ist. Sonst blendet das Fernlicht dessen Fahrer über die Spiegel."),
("Wann müssen Sie bei Dunkelheit von Fernlicht auf Abblendlicht umschalten?",
 "Wenn Ihnen jemand entgegenkommt", ["Erst wenn der Gegenverkehr 30 m entfernt ist", "Nur innerhalb von Ortschaften", "Nur auf Autobahnen"],
 "§ 17 Abs. 2 StVO: Es ist rechtzeitig abzublenden, wenn ein Fahrzeug entgegenkommt oder mit geringem Abstand vorausfährt."),
("Sie stehen an einer roten Ampel, die Start-Stopp-Automatik hat den Motor ausgeschaltet. Dürfen Sie das Handy in die Hand nehmen?",
 "Nein, der Motor ist nicht ganz aus", ["Ja, das Auto steht ja", "Ja, aber nur zum Telefonieren", "Ja, bis die Ampel Gelb zeigt"],
 "§ 23 Abs. 1b StVO: Die Ausnahme gilt nur, wenn der Motor vollständig ausgeschaltet ist. Eine automatische Abschaltung zählt nicht."),
("Ihr Handy klingelt während der Fahrt. Wie dürfen Sie das Gespräch annehmen?",
 "Über eine Freisprecheinrichtung", ["Kurz in die Hand nehmen", "Nur auf geraden Strecken", "Zwischen Schulter und Ohr klemmen"],
 "§ 23 Abs. 1a StVO: Ein Handy darf während der Fahrt nicht aufgenommen oder gehalten werden. Erlaubt ist die Bedienung per Sprachsteuerung oder Freisprechanlage."),
("Wann dürfen Sie hupen?",
 "Wenn Sie sich oder andere gefährdet sehen", ["Wenn der Vordermann bei Grün zu lange zögert", "Zum Grüßen von Bekannten", "Wenn Sie es eilig haben"],
 "§ 16 Abs. 1 StVO: Schallzeichen sind außerhalb von Ortschaften beim Überholen und bei Gefahr erlaubt, sonst nicht."),
("Am Bahnübergang leuchtet das Lichtzeichen gelb auf. Was gilt für Sie?",
 "Vor dem Andreaskreuz warten", ["Zügig über die Gleise fahren", "Nur bei Rot anhalten", "Langsam über die Gleise rollen"],
 "§ 19 Abs. 2 StVO: Bei gelben oder roten Lichtzeichen, rotem Blinklicht oder sich senkenden Schranken muss vor dem Andreaskreuz gewartet werden."),
("Vor Ihnen fährt ein Fahrzeug mit Anhänger gerade über einen Bahnübergang. Wann fahren Sie nach?",
 "Wenn hinter den Gleisen Platz ist", ["Sofort, solange die Schranke oben ist", "Wenn der Zug noch weit genug weg ist", "Wenn Sie dicht dahinterbleiben"],
 "§ 19 Abs. 4 StVO: Wer nicht zügig und ohne Aufenthalt über den Bahnübergang fahren kann, muss vor dem Andreaskreuz warten."),
("Sie wollen auf einer Straße mit Gegenverkehr links abbiegen. Wo ordnen Sie sich rechtzeitig ein?",
 "Links bis zur Fahrbahnmitte", ["Am rechten Fahrbahnrand", "Auf dem Fahrstreifen des Gegenverkehrs", "In der Mitte ohne zu blinken"],
 "§ 9 Abs. 1 StVO: Linksabbieger ordnen sich bis zur Mitte der Fahrbahn ein, in Einbahnstraßen möglichst weit links, und kündigen das rechtzeitig an."),
]
